import{PROJECTION_FIXTURES}from'./fixtures.mjs';
export const initialProjectionState=()=>({fixture:'finite',sourceX:120,sourceY:-80,noise:0,mismatch:0,sigma:.25,selected:2,lines:true,seed:29029});
export function validateProjectionState(input){const s=structuredClone(input),range=(key,min,max)=>{if(typeof s[key]!=='number'||!Number.isFinite(s[key])||s[key]<min||s[key]>max)throw Error('Invalid '+key);};if(!s||!Object.hasOwn(PROJECTION_FIXTURES,s.fixture))throw Error('Unknown fixture');range('sourceX',-10000,10000);range('sourceY',-10000,10000);range('noise',0,10);range('mismatch',-80,80);range('sigma',.01,20);range('selected',0,11);if(!Number.isInteger(s.selected)||s.seed!==29029||typeof s.lines!=='boolean')throw Error('Invalid selection or sampling rule');return s;}
export function syntheticInput(input){const s=validateProjectionState(input),f=structuredClone(PROJECTION_FIXTURES[s.fixture]);if(s.fixture==='finite')f.pairs.forEach((p,i)=>{const k=1.2+.1*(i%3);p.receiver=p.aperture.map((v,j)=>(j?s.sourceY:s.sourceX)+k*(v-(j?s.sourceY:s.sourceX)));});let seed=s.seed;const random=()=>{seed=(1664525*seed+1013904223)>>>0;return(seed+.5)/4294967296;},normal=()=>Math.sqrt(-2*Math.log(random()))*Math.cos(2*Math.PI*random());for(const p of f.pairs){p.sigma_px=s.sigma;for(const k of ['aperture','receiver'])p[k]=p[k].map(v=>v+s.noise*normal());}const p=f.pairs[2],dx=p.receiver[0]-p.aperture[0],dy=p.receiver[1]-p.aperture[1],n=Math.hypot(dx,dy);if(n){p.receiver[0]-=s.mismatch*dy/n;p.receiver[1]+=s.mismatch*dx/n;}return f;}
